#!/usr/bin/env Rscript
############################################################
## INDEPENDENT AMINOGLYCOSIDE MAGeCK POSTPROCESSING + QC
## Run from the project root by sourcing this complete file in R/RStudio.
## Upstream: 01_MAGeCK_preprocessing_and_run.R → generated master Bash runner.
## Inputs: MAGeCK_data/mageck_rra_raw_AG/ with 19 primary gene_summary.txt files,
## the four b*_MAGeCK_fullmatch_raw_counts.tsv matrices and the combined manifest.
## Also requires the supplied B4 TOB1 TOTALNORM gene summary; that auxiliary
## file is read unconditionally and is not generated by the 19-test runner.
## Outputs: MAGeCK_data/mageck_rra_postprocessing_AG/ contains TSV/TSV.gz results,
## settings and QC tables/plots; XLSX is disabled by default. The all-gene drug
## catalogue is read by preprocessing scripts 04_AMG_compare_MAGeCK_Stouffer.R
## and 15_AMG_MH_FBS_MAGeCK.R.
##
## This script is independent of edgeR/MetaCounter and reads only
## the full-match MAGeCK analysis produced by:
##   MAGeCK_data/01_MAGeCK_preprocessing_and_run.R
##
## EXPECTED CONTRASTS
## ------------------
## 19 primary MAGeCK contrasts total:
##   7 drug-vs-matched-no-drug contrasts
##     -> PRIMARY gene-drug interaction tests
##   5 untreated-post-vs-T0 baseline contrasts
##     -> B1 T1, B1 T2, B2 T1, B3 T1, B4 T1
##   7 drug-vs-T0 contrasts
##     -> total treated fitness relative to T0
##
## DIRECT CONDITIONS
## -----------------
##   TOB 0.025 T1
##   TOB 0.1   T1
##   TOB 0.4   T1
##   TOB 1     T1
##   TOB 0.4   T2
##   AMK 2     T1
##   FBS 60    T1
##
## T2 is analyzed explicitly against its matched untreated T2 control.
## T2 and FBS are retained in the full interaction catalogue but excluded
## from aminoglycoside recurrence counting.
##
## TOB 1 NORMALIZATION SENSITIVITY
## -------------------------------
## The primary 19-contrast catalogue remains the original median-normalized
## MAGeCK analysis. A separate TOTALNORM rerun is read ONLY for the direct
## B4 TOB 1 T1 vs None T1 contrast. It is never counted as a 20th contrast.
##
## For recurrence ONLY, TOB 1 support is accepted conservatively when the
## same directional call is significant (FDR < cutoff) under BOTH median
## and total normalization. All other TOB doses and AMK are left unchanged.
##
## PRIMARY MAGeCK CALL
## -------------------
## negative-selection FDR < cutoff  -> negative selection
## positive-selection FDR < cutoff  -> positive selection
## neither                           -> not significant
## both                              -> ambiguous_bidirectional
##
## Biological labels:
##   direct drug contrasts:
##     negative -> sensitizing
##     positive -> tolerance_inducing
##   untreated post-vs-T0:
##     negative -> fitness_decreasing
##     positive -> fitness_increasing
##   drug-vs-T0:
##     negative -> treated_fitness_decreasing
##     positive -> treated_fitness_increasing
##
## IMPORTANT:
##   drug-vs-T0 calls are NOT gene-drug interaction calls.
##   Interaction labels come ONLY from drug-vs-matched-control contrasts.
##
## Input contains full-match/perfect guides only.
## No mismatch guides are used anywhere in this analysis.
############################################################
# ============================================================
# 1. PACKAGES
# ============================================================
required_packages <- c("data.table", "openxlsx", "ggplot2", "scales")

missing_packages <- required_packages[!vapply(required_packages, requireNamespace, logical(1), 
  quietly = TRUE)]

if (length(missing_packages) > 0L) {
  stop("Missing required package(s): ", paste(missing_packages, collapse = ", "), "\nInstall them first, for example:\n", 
    "install.packages(c(", paste(sprintf("\"%s\"", missing_packages), collapse = ", "), "))")
}

suppressPackageStartupMessages({
  library(data.table)
  library(openxlsx)
  library(ggplot2)
})

# ============================================================
# 2. USER SETTINGS
# ============================================================
MAGECK_DIR <- "MAGeCK_data/mageck_rra_raw_AG"

PREPROCESS_CONTRAST_MANIFEST_FILE <- file.path(MAGECK_DIR, "all_batches_MAGeCK_contrast_manifest.tsv")

VERIFY_AGAINST_PREPROCESS_MANIFEST <- TRUE

OUTPUT_DIR <- "MAGeCK_data/mageck_rra_postprocessing_AG"

QC_DIR <- file.path(OUTPUT_DIR, "QC")

dir.create(OUTPUT_DIR, recursive = TRUE, showWarnings = FALSE)

dir.create(QC_DIR, recursive = TRUE, showWarnings = FALSE)

# MAGeCK's own gene-level FDR threshold for the working call.
MAGECK_FDR_CUT <- 0.05

# T2 is an intentional part of this aminoglycoside experiment.
STRICT_EXPECTED_COUNTS <- TRUE

EXPECTED_TOTAL_CONTRASTS <- 19L

EXPECTED_DRUG_CONTRASTS <- 7L

EXPECTED_BASELINE_CONTRASTS <- 5L

EXPECTED_TREATED_VS_T0_CONTRASTS <- 7L

EXPECTED_T2_CONTRASTS <- 3L

# Recurrence uses only the five independent aminoglycoside T1 conditions:
# 4x TOB + AMK. Both T2 and FBS are excluded from recurrence.
RECURRENCE_TIMINGS <- c("T1")

RECURRENCE_DRUGS <- c("TOB", "AMK")

# Manuscript display order.
MANUSCRIPT_CONDITION_ORDER <- c("TOB 0.025 T1 | B4", "TOB 0.1 T1 | B4", "TOB 0.4 T1 | B1", "TOB 1 T1 | B4", 
  "TOB 0.4 T2 | B1", "AMK 2 T1 | B2", "FBS 60 T1 | B3")

# QC flags only. These do NOT filter MAGeCK results.
LOW_GUIDE_COUNT_WARN <- 3L

HIGH_ZERO_FRACTION_WARN <- 0.5

LOW_DETECTED_GUIDE_FRACTION_WARN <- 0.5

LOW_REPLICATE_SPEARMAN_WARN <- 0.8

# Number of variable guides used for PCA.
PCA_TOP_VARIABLE_GUIDES <- 5000L

# Number of top negative/positive genes exported per contrast
# regardless of significance.
TOP_N_PER_DIRECTION <- 50L

# Plot settings.
BASE_FAMILY <- "sans"

PLOT_DPI <- 300

PLOT_WIDTH <- 8

PLOT_HEIGHT <- 6

WRITE_XLSX <- FALSE

# Special normalization-sensitivity check for ONLY the direct B4 TOB 1 T1 contrast.
# This file is excluded from the 19 primary contrasts and is used only as a
# secondary robustness check for TOB 1 recurrence support.
TOB1_TOTALNORM_FILE <- file.path(MAGECK_DIR, "b4", "results", "b4_TOB_1_T1_vs_None_0_T1_TOTALNORM.gene_summary.txt")

USE_TOB1_CONCORDANT_ONLY_FOR_RECURRENCE <- TRUE

# ============================================================
# 3. GENERIC HELPERS
# ============================================================
classify_guide_design <- function(n_guides) {
  data.table::fcase(is.na(n_guides), "missing", n_guides == 1, "1-guide", n_guides == 2, "2-guide", 
    n_guides == 10, "10-guide", n_guides == 28, "28-guide", default = "other")
}

# Group replicates after removing the batch/sample number from GEO or original IDs.
strip_replicate_prefix <- function(x) {
  sub("^([bB][0-9]+_)?[0-9]+[-_]", "", as.character(x))
}

gini_coefficient <- function(x) {
  x <- suppressWarnings(as.numeric(x))
  x <- x[is.finite(x) & x >= 0]
  if (length(x) == 0L) {
    return(NA_real_)
  }
  if (sum(x) == 0) {
    return(0)
  }
  x <- sort(x)
  n <- length(x)
  (2 * sum(seq_len(n) * x)/(n * sum(x))) - (n + 1)/n
}

save_plot_png_pdf <- function(plot_object, filename_stem, width = PLOT_WIDTH, height = PLOT_HEIGHT) {
  png_file <- file.path(QC_DIR, paste0(filename_stem, ".png"))
  pdf_file <- file.path(QC_DIR, paste0(filename_stem, ".pdf"))
  ggplot2::ggsave(filename = png_file, plot = plot_object, width = width, height = height, units = "in", 
    dpi = PLOT_DPI)
  ggplot2::ggsave(filename = pdf_file, plot = plot_object, width = width, height = height, units = "in")
  invisible(c(png_file, pdf_file))
}

write_sheet_safe <- function(wb, sheet_name, x) {
  sheet_name <- substr(sheet_name, 1, 31)
  openxlsx::addWorksheet(wb, sheet_name)
  openxlsx::writeData(wb, sheet_name, as.data.frame(x))
  invisible(NULL)
}

parse_group_label <- function(x) {
  pieces <- strsplit(as.character(x), "_", fixed = TRUE)[[1]]
  if (length(pieces) < 3L) {
    return(data.table::data.table(drug = NA_character_, dose = NA_character_, timing = NA_character_))
  }
  timing <- pieces[length(pieces)]
  dose <- pieces[length(pieces) - 1L]
  drug <- paste(pieces[seq_len(length(pieces) - 2L)], collapse = "_")
  data.table::data.table(drug = drug, dose = dose, timing = timing)
}

parse_mageck_filename <- function(path) {
  filename <- basename(path)
  prefix <- sub("\\.gene_summary\\.txt$", "", filename)
  batch <- sub("_.*$", "", prefix)
  contrast_id <- sub(paste0("^", batch, "_"), "", prefix)
  if (!grepl("_vs_", contrast_id, fixed = TRUE)) {
    stop("Could not parse MAGeCK comparison from filename:\n", filename)
  }
  shift <- sub("_vs_.*$", "", contrast_id)
  base <- sub("^.*_vs_", "", contrast_id)
  shift_info <- parse_group_label(shift)
  base_info <- parse_group_label(base)
  comparison_type <- if (identical(shift_info$drug, "None") && identical(base_info$drug, "None") && 
    !identical(shift_info$timing, "T0") && identical(base_info$timing, "T0")) {
    "baseline_post_vs_T0"
  } else if (!identical(shift_info$drug, "None") && identical(base_info$drug, "None") && identical(shift_info$timing, 
    base_info$timing)) {
    "drug_vs_matched_control"
  } else if (!identical(shift_info$drug, "None") && identical(base_info$drug, "None") && !identical(shift_info$timing, 
    "T0") && identical(base_info$timing, "T0")) {
    "drug_vs_T0"
  } else {
    "other"
  }
  display_label <- if (comparison_type == "drug_vs_matched_control") {
    paste0(shift_info$drug, " ", shift_info$dose, " ", shift_info$timing, " | ", toupper(batch))
  } else if (comparison_type == "baseline_post_vs_T0") {
    paste0("None ", shift_info$timing, " vs T0 | ", toupper(batch))
  } else if (comparison_type == "drug_vs_T0") {
    paste0(shift_info$drug, " ", shift_info$dose, " ", shift_info$timing, " vs T0 | ", toupper(batch))
  } else {
    paste0(shift, " vs ", base, " | ", toupper(batch))
  }
  data.table::data.table(batch = tolower(batch), mageck_prefix = prefix, contrast_id = contrast_id, 
    shift = shift, base = base, comparison_type = comparison_type, shift_drug = shift_info$drug, 
    shift_dose = shift_info$dose, shift_timing = shift_info$timing, base_drug = base_info$drug, 
    base_dose = base_info$dose, base_timing = base_info$timing, display_label = display_label)
}

# ============================================================
# 4. RAW COUNT MATRIX HELPERS
# ============================================================
read_mageck_count_matrix <- function(path) {
  dt <- data.table::fread(path, sep = "\t", header = TRUE, data.table = TRUE, check.names = FALSE)
  if (ncol(dt) < 3L) {
    stop("Count matrix has fewer than 3 columns:\n", path)
  }
  required_first <- c("sgRNA", "Gene")
  if (!all(required_first %in% names(dt))) {
    stop("Count matrix must contain sgRNA and Gene columns:\n", path)
  }
  sample_columns <- setdiff(names(dt), required_first)
  for (sample_i in sample_columns) {
    dt[, `:=`((sample_i), suppressWarnings(as.numeric(get(sample_i))))]
    if (any(!is.finite(dt[[sample_i]]))) {
      stop("Non-finite count detected in ", basename(path), " sample ", sample_i)
    }
    if (any(dt[[sample_i]] < 0)) {
      stop("Negative count detected in ", basename(path), " sample ", sample_i)
    }
  }
  list(data = dt, sample_columns = sample_columns)
}

make_sample_qc <- function(count_dt, sample_columns, batch_id, matrix_type) {
  n_guides <- nrow(count_dt)
  out <- data.table::rbindlist(lapply(sample_columns, function(sample_i) {
    x <- count_dt[[sample_i]]
    total_reads <- sum(x)
    detected_guides <- sum(x > 0)
    zero_guides <- sum(x == 0)
    data.table::data.table(batch = batch_id, matrix_type = matrix_type, sample = sample_i, 
      sample_group = strip_replicate_prefix(sample_i), n_guides = n_guides, total_reads = total_reads, 
      detected_guides = detected_guides, detected_guide_fraction = detected_guides/n_guides, 
      zero_guides = zero_guides, zero_fraction = zero_guides/n_guides, median_count = stats::median(x), 
      mean_count = mean(x), q25_count = as.numeric(stats::quantile(x, probs = 0.25, names = FALSE)), 
      q75_count = as.numeric(stats::quantile(x, probs = 0.75, names = FALSE)), max_count = max(x), 
      gini = gini_coefficient(x))
  }), use.names = TRUE, fill = TRUE)
  out[, `:=`(high_zero_fraction_flag, zero_fraction >= HIGH_ZERO_FRACTION_WARN)]
  out[, `:=`(low_detected_fraction_flag, detected_guide_fraction <= LOW_DETECTED_GUIDE_FRACTION_WARN)]
  out[]
}

make_logcpm_matrix <- function(count_dt, sample_columns) {
  mat <- as.matrix(count_dt[, ..sample_columns])
  storage.mode(mat) <- "double"
  library_sizes <- colSums(mat)
  if (any(library_sizes <= 0)) {
    stop("At least one sample has zero total counts.")
  }
  cpm <- sweep(mat, 2, library_sizes, "/") * 1e+06
  log2(cpm + 1)
}

make_correlation_tables <- function(log_matrix, sample_columns, batch_id) {
  pearson_mat <- stats::cor(log_matrix, method = "pearson", use = "pairwise.complete.obs")
  spearman_mat <- stats::cor(log_matrix, method = "spearman", use = "pairwise.complete.obs")
  pearson_long <- data.table::as.data.table(as.table(pearson_mat))
  data.table::setnames(pearson_long, c("sample1", "sample2", "correlation"))
  pearson_long[, `:=`(batch, batch_id)]
  pearson_long[, `:=`(method, "pearson_logCPM")]
  spearman_long <- data.table::as.data.table(as.table(spearman_mat))
  data.table::setnames(spearman_long, c("sample1", "sample2", "correlation"))
  spearman_long[, `:=`(batch, batch_id)]
  spearman_long[, `:=`(method, "spearman_logCPM")]
  all_long <- data.table::rbindlist(list(pearson_long, spearman_long), use.names = TRUE, fill = TRUE)
  all_long[, `:=`(group1, strip_replicate_prefix(sample1))]
  all_long[, `:=`(group2, strip_replicate_prefix(sample2))]
  all_long[, `:=`(same_group, group1 == group2)]
  all_long[, `:=`(self_pair, sample1 == sample2)]
  replicate_summary <- all_long[self_pair == FALSE & same_group == TRUE, .(n_pairs = .N, mean_correlation = mean(correlation, 
    na.rm = TRUE), min_correlation = min(correlation, na.rm = TRUE), max_correlation = max(correlation, 
    na.rm = TRUE)), by = .(batch, method, group1)]
  data.table::setnames(replicate_summary, "group1", "sample_group")
  replicate_summary[, `:=`(low_replicate_correlation_flag, method == "spearman_logCPM" & min_correlation < 
    LOW_REPLICATE_SPEARMAN_WARN)]
  list(long = all_long, replicate_summary = replicate_summary, pearson_matrix = pearson_mat, 
    spearman_matrix = spearman_mat)
}

plot_correlation_heatmap <- function(correlation_long, batch_id, method_name) {
  plot_dt <- correlation_long[method == method_name]
  p <- ggplot2::ggplot(plot_dt, ggplot2::aes(x = sample1, y = sample2, fill = correlation)) + 
    ggplot2::geom_tile() + ggplot2::geom_text(ggplot2::aes(label = sprintf("%.2f", correlation)), 
    size = 3) + ggplot2::scale_fill_gradient(low = "white", high = "black", limits = c(0, 1), 
    oob = scales::squish) + ggplot2::labs(x = NULL, y = NULL, fill = "Correlation", title = paste0(toupper(batch_id), 
    " full-match guide ", gsub("_", " ", method_name), " correlation")) + ggplot2::theme_bw(base_size = 11, 
    base_family = BASE_FAMILY) + ggplot2::theme(axis.text.x = ggplot2::element_text(angle = 45, 
    hjust = 1), panel.grid = ggplot2::element_blank())
  p
}

make_pca <- function(log_matrix, sample_columns, batch_id) {
  guide_variance <- apply(log_matrix, 1, stats::var, na.rm = TRUE)
  finite_idx <- is.finite(guide_variance)
  if (sum(finite_idx) < 2L) {
    return(NULL)
  }
  keep_idx <- which(finite_idx)
  if (length(keep_idx) > PCA_TOP_VARIABLE_GUIDES) {
    keep_idx <- keep_idx[order(guide_variance[keep_idx], decreasing = TRUE)[seq_len(PCA_TOP_VARIABLE_GUIDES)]]
  }
  pca <- stats::prcomp(t(log_matrix[keep_idx, , drop = FALSE]), center = TRUE, scale. = FALSE)
  variance_fraction <- (pca$sdev^2)/sum(pca$sdev^2)
  scores <- data.table::as.data.table(pca$x)
  scores[, `:=`(sample, rownames(pca$x))]
  scores[, `:=`(sample_group, strip_replicate_prefix(sample))]
  scores[, `:=`(batch, batch_id)]
  list(scores = scores, variance_fraction = variance_fraction, n_guides_used = length(keep_idx))
}

plot_pca <- function(pca_result, batch_id) {
  if (is.null(pca_result)) {
    return(NULL)
  }
  scores <- pca_result$scores
  pc1_var <- 100 * pca_result$variance_fraction[1]
  pc2_var <- if (length(pca_result$variance_fraction) >= 2L) {
    100 * pca_result$variance_fraction[2]
  } else {
    0
  }
  p <- ggplot2::ggplot(scores, ggplot2::aes(x = PC1, y = PC2, label = sample)) + ggplot2::geom_point(size = 3) + 
    ggplot2::geom_text(nudge_y = 0.15, check_overlap = TRUE, size = 3.3) + ggplot2::labs(x = sprintf("PC1 (%.1f%%)", 
    pc1_var), y = sprintf("PC2 (%.1f%%)", pc2_var), title = paste0(toupper(batch_id), " full-match guide PCA"), 
    subtitle = paste0("Top ", pca_result$n_guides_used, " variable guides; log2(CPM + 1), QC only")) + 
    ggplot2::theme_bw(base_size = 11, base_family = BASE_FAMILY)
  p
}

make_control_qc <- function(control_dt, control_samples, fullmatch_sample_metrics, batch_id) {
  full_lib <- fullmatch_sample_metrics[matrix_type == "fullmatch", .(sample, fullmatch_total_reads = total_reads)]
  missing_samples <- setdiff(control_samples, full_lib$sample)
  if (length(missing_samples) > 0L) {
    stop(batch_id, ": control audit matrix contains sample(s) missing from full-match matrix: ", 
      paste(missing_samples, collapse = ", "))
  }
  long <- data.table::melt(control_dt, id.vars = c("sgRNA", "Gene"), measure.vars = control_samples, 
    variable.name = "sample", value.name = "count")
  long <- merge(long, full_lib, by = "sample", all.x = TRUE, sort = FALSE)
  long[, `:=`(sample_group, strip_replicate_prefix(sample))]
  long[, `:=`(batch, batch_id)]
  long[, `:=`(normalized_cpm_fullmatch_library, count/fullmatch_total_reads * 1e+06)]
  long[, `:=`(log2_normalized_cpm, log2(normalized_cpm_fullmatch_library + 1))]
  summary <- long[, .(n_control_guides = .N, detected_control_guides = sum(count > 0), zero_control_fraction = mean(count == 
    0), median_raw_control_count = stats::median(count), median_log2_normalized_cpm = stats::median(log2_normalized_cpm), 
    mean_log2_normalized_cpm = mean(log2_normalized_cpm)), by = .(batch, sample, sample_group)]
  group_summary <- summary[, .(n_replicates = .N, median_of_sample_medians = stats::median(median_log2_normalized_cpm), 
    range_of_sample_medians = diff(range(median_log2_normalized_cpm)), median_zero_control_fraction = stats::median(zero_control_fraction)), 
    by = .(batch, sample_group)]
  list(long = long, sample_summary = summary, group_summary = group_summary)
}

plot_control_distribution <- function(control_long, batch_id) {
  p <- ggplot2::ggplot(control_long, ggplot2::aes(x = sample, y = log2_normalized_cpm)) + ggplot2::geom_boxplot(outlier.size = 0.4) + 
    ggplot2::labs(x = NULL, y = "Control guide log2(CPM + 1)", title = paste0(toupper(batch_id), 
      " non-targeting-control guide abundance"), subtitle = "Normalized only for QC by full-match library size") + 
    ggplot2::theme_bw(base_size = 11, base_family = BASE_FAMILY) + ggplot2::theme(axis.text.x = ggplot2::element_text(angle = 45, 
    hjust = 1))
  p
}

# ============================================================
# 5. MAGeCK RESULT READER
# ============================================================
read_mageck_gene_summary <- function(path) {
  dt <- data.table::fread(path, sep = "\t", header = TRUE, data.table = TRUE, check.names = FALSE)
  required <- c("id", "num", "neg|score", "neg|p-value", "neg|fdr", "neg|rank", "neg|goodsgrna", 
    "neg|lfc", "pos|score", "pos|p-value", "pos|fdr", "pos|rank", "pos|goodsgrna", "pos|lfc")
  missing_required <- setdiff(required, names(dt))
  if (length(missing_required) > 0L) {
    stop("MAGeCK file is missing required columns:\n", path, "\nMissing: ", paste(missing_required, 
      collapse = ", "))
  }
  data.table::setnames(dt, old = required, new = c("PAO1_ID", "num_guides", "neg_score", "neg_pvalue", 
    "neg_fdr", "neg_rank", "neg_goodsgrna", "neg_lfc", "pos_score", "pos_pvalue", "pos_fdr", 
    "pos_rank", "pos_goodsgrna", "pos_lfc"))
  dt[, `:=`(PAO1_ID, trimws(as.character(PAO1_ID)))]
  numeric_columns <- c("num_guides", "neg_score", "neg_pvalue", "neg_fdr", "neg_rank", "neg_goodsgrna", 
    "neg_lfc", "pos_score", "pos_pvalue", "pos_fdr", "pos_rank", "pos_goodsgrna", "pos_lfc")
  for (column_i in numeric_columns) {
    dt[, `:=`((column_i), suppressWarnings(as.numeric(get(column_i))))]
  }
  info <- parse_mageck_filename(path)
  dt[, `:=`(batch, info$batch)]
  dt[, `:=`(mageck_prefix, info$mageck_prefix)]
  dt[, `:=`(contrast_id, info$contrast_id)]
  dt[, `:=`(shift, info$shift)]
  dt[, `:=`(base, info$base)]
  dt[, `:=`(comparison_type, info$comparison_type)]
  dt[, `:=`(shift_drug, info$shift_drug)]
  dt[, `:=`(shift_dose, info$shift_dose)]
  dt[, `:=`(shift_timing, info$shift_timing)]
  dt[, `:=`(base_drug, info$base_drug)]
  dt[, `:=`(base_dose, info$base_dose)]
  dt[, `:=`(base_timing, info$base_timing)]
  dt[, `:=`(display_label, info$display_label)]
  dt[, `:=`(source_file, normalizePath(path, mustWork = TRUE))]
  dt[, `:=`(gene_lfc, neg_lfc)]
  inconsistent_lfc <- dt[is.finite(neg_lfc) & is.finite(pos_lfc) & abs(neg_lfc - pos_lfc) > 1e-10]
  if (nrow(inconsistent_lfc) > 0L) {
    warning(basename(path), ": ", nrow(inconsistent_lfc), " genes have different neg|lfc and pos|lfc values.")
  }
  dt[, `:=`(neg_goods_fraction, data.table::fifelse(is.finite(num_guides) & num_guides > 0, neg_goodsgrna/num_guides, 
    NA_real_))]
  dt[, `:=`(pos_goods_fraction, data.table::fifelse(is.finite(num_guides) & num_guides > 0, pos_goodsgrna/num_guides, 
    NA_real_))]
  dt[, `:=`(low_guide_count_flag, is.finite(num_guides) & num_guides < LOW_GUIDE_COUNT_WARN)]
  dt[]
}

# Read the separate TOB 1 TOTALNORM sensitivity rerun without parsing it as
# an ordinary contrast. The returned columns are deliberately prefixed so
# they cannot overwrite the primary median-normalized MAGeCK results.
read_tob1_totalnorm_summary <- function(path) {
  if (!file.exists(path)) {
    stop("TOB 1 TOTALNORM sensitivity file is missing:\n", path)
  }
  dt <- data.table::fread(path, sep = "\t", header = TRUE, data.table = TRUE, check.names = FALSE)
  required <- c("id", "num", "neg|fdr", "neg|lfc", "pos|fdr", "pos|lfc")
  missing_required <- setdiff(required, names(dt))
  if (length(missing_required) > 0L) {
    stop("TOB 1 TOTALNORM file is missing required column(s): ", paste(missing_required, collapse = ", "))
  }
  out <- dt[, .(PAO1_ID = trimws(as.character(id)), totalnorm_num_guides = suppressWarnings(as.numeric(num)), 
    totalnorm_neg_fdr = suppressWarnings(as.numeric(`neg|fdr`)), totalnorm_neg_lfc = suppressWarnings(as.numeric(`neg|lfc`)), 
    totalnorm_pos_fdr = suppressWarnings(as.numeric(`pos|fdr`)), totalnorm_pos_lfc = suppressWarnings(as.numeric(`pos|lfc`)))]
  out[, `:=`(totalnorm_neg_significant, is.finite(totalnorm_neg_fdr) & totalnorm_neg_fdr < MAGECK_FDR_CUT)]
  out[, `:=`(totalnorm_pos_significant, is.finite(totalnorm_pos_fdr) & totalnorm_pos_fdr < MAGECK_FDR_CUT)]
  out[, `:=`(totalnorm_biological_call, data.table::fcase(totalnorm_neg_significant & totalnorm_pos_significant, 
    "ambiguous_bidirectional", totalnorm_neg_significant, "sensitizing", totalnorm_pos_significant, 
    "tolerance_inducing", default = "not_significant"))]
  out[]
}

# ============================================================
# 6. RAW INPUT QC — DISCOVER BATCHES
# ============================================================
# Use the prepared batch folders to locate the count matrices used by MAGeCK.
# This stage checks the inputs; it does not refit the screen.
if (!dir.exists(MAGECK_DIR)) {
  stop("MAGeCK directory does not exist:\n", MAGECK_DIR)
}

batch_dirs <- list.dirs(MAGECK_DIR, recursive = FALSE, full.names = TRUE)

batch_dirs <- batch_dirs[grepl("^b[0-9]+$", basename(batch_dirs), ignore.case = TRUE)]

batch_dirs <- sort(batch_dirs)

if (length(batch_dirs) == 0L) {
  stop("No batch directories b1, b2, ... found under:\n", MAGECK_DIR)
}

# ============================================================
# 7. RAW INPUT QC — PER BATCH
# ============================================================
# Summarize sequencing depth, guide detection and replicate agreement from
# the prepared matrices. QC flags describe potential problems; they do not remove samples.
sample_qc_list <- list()

correlation_list <- list()

replicate_summary_list <- list()

pca_score_list <- list()

control_sample_list <- list()

control_group_list <- list()

input_guide_count_list <- list()

for (batch_dir_i in batch_dirs) {
  batch_id <- tolower(basename(batch_dir_i))
  message("\nRaw-count QC: ", batch_id)
  fullmatch_file <- file.path(batch_dir_i, paste0(batch_id, "_MAGeCK_fullmatch_raw_counts.tsv"))
  if (!file.exists(fullmatch_file)) {
    stop("Missing full-match MAGeCK count matrix:\n", fullmatch_file)
  }
  full_obj <- read_mageck_count_matrix(fullmatch_file)
  full_dt <- full_obj$data
  full_samples <- full_obj$sample_columns
  input_guide_count_i <- full_dt[, .(input_fullmatch_guides = as.integer(.N)), by = .(PAO1_ID = Gene)]
  input_guide_count_i[, `:=`(PAO1_ID, trimws(as.character(PAO1_ID)))]
  input_guide_count_i[, `:=`(batch, batch_id)]
  input_guide_count_i[, `:=`(guide_design_class, classify_guide_design(input_fullmatch_guides))]
  input_guide_count_list[[batch_id]] <- input_guide_count_i
  sample_qc_i <- make_sample_qc(count_dt = full_dt, sample_columns = full_samples, batch_id = batch_id, 
    matrix_type = "fullmatch")
  sample_qc_list[[paste0(batch_id, "_fullmatch")]] <- sample_qc_i
  logcpm_i <- make_logcpm_matrix(count_dt = full_dt, sample_columns = full_samples)
  correlation_i <- make_correlation_tables(log_matrix = logcpm_i, sample_columns = full_samples, 
    batch_id = batch_id)
  correlation_list[[batch_id]] <- correlation_i$long
  replicate_summary_list[[batch_id]] <- correlation_i$replicate_summary
  p_spearman <- plot_correlation_heatmap(correlation_long = correlation_i$long, batch_id = batch_id, 
    method_name = "spearman_logCPM")
  save_plot_png_pdf(p_spearman, paste0("QC_01_", batch_id, "_replicate_correlation_spearman"), 
    width = 7, height = 6)
  pca_i <- make_pca(log_matrix = logcpm_i, sample_columns = full_samples, batch_id = batch_id)
  if (!is.null(pca_i)) {
    pca_score_list[[batch_id]] <- pca_i$scores
    p_pca <- plot_pca(pca_result = pca_i, batch_id = batch_id)
    save_plot_png_pdf(p_pca, paste0("QC_02_", batch_id, "_PCA_fullmatch_guides"), width = 7, 
      height = 6)
  }
  control_file <- file.path(batch_dir_i, paste0(batch_id, "_control_raw_counts_AUDIT.tsv"))
  if (file.exists(control_file)) {
    control_obj <- read_mageck_count_matrix(control_file)
    control_dt <- control_obj$data
    control_samples <- control_obj$sample_columns
    control_sample_qc_i <- make_sample_qc(count_dt = control_dt, sample_columns = control_samples, 
      batch_id = batch_id, matrix_type = "control")
    sample_qc_list[[paste0(batch_id, "_control")]] <- control_sample_qc_i
    control_qc_i <- make_control_qc(control_dt = control_dt, control_samples = control_samples, 
      fullmatch_sample_metrics = sample_qc_i, batch_id = batch_id)
    control_sample_list[[batch_id]] <- control_qc_i$sample_summary
    control_group_list[[batch_id]] <- control_qc_i$group_summary
    p_control <- plot_control_distribution(control_long = control_qc_i$long, batch_id = batch_id)
    save_plot_png_pdf(p_control, paste0("QC_03_", batch_id, "_control_guide_distribution"), 
      width = 8, height = 6)
  } else {
    message(batch_id, ": control-guide QC skipped (full-match-only aminoglycoside pipeline).")
  }
}

sample_qc <- data.table::rbindlist(sample_qc_list, use.names = TRUE, fill = TRUE)

correlation_long <- data.table::rbindlist(correlation_list, use.names = TRUE, fill = TRUE)

replicate_correlation_summary <- data.table::rbindlist(replicate_summary_list, use.names = TRUE, 
  fill = TRUE)

pca_scores <- data.table::rbindlist(pca_score_list, use.names = TRUE, fill = TRUE)

control_sample_summary <- data.table::rbindlist(control_sample_list, use.names = TRUE, fill = TRUE)

control_group_summary <- data.table::rbindlist(control_group_list, use.names = TRUE, fill = TRUE)

input_guide_counts <- data.table::rbindlist(input_guide_count_list, use.names = TRUE, fill = TRUE)

input_guide_counts[, `:=`(batch, tolower(trimws(as.character(batch))))]

input_guide_counts[, `:=`(PAO1_ID, trimws(as.character(PAO1_ID)))]

# ============================================================
# 8. RAW INPUT QC — OVERALL FLAGS
# ============================================================
sample_qc[, `:=`(any_sample_qc_flag, high_zero_fraction_flag | low_detected_fraction_flag)]

raw_qc_flags <- sample_qc[any_sample_qc_flag == TRUE]

replicate_qc_flags <- replicate_correlation_summary[low_replicate_correlation_flag == TRUE]

# ============================================================
# 9. LOCATE MAGeCK GENE SUMMARIES
# ============================================================
# Read primary gene summaries, excluding the separately named TOTALNORM file.
# A gene summary is required for each comparison in the preparation manifest.
mageck_files <- list.files(MAGECK_DIR, pattern = "\\.gene_summary\\.txt$", recursive = TRUE, full.names = TRUE)

# IMPORTANT: normalization-sensitivity reruns are NOT primary contrasts.
# Exclude them before manifest validation and primary postprocessing.
mageck_files <- mageck_files[!grepl("_TOTALNORM\\.gene_summary\\.txt$", basename(mageck_files), 
  ignore.case = TRUE)]

mageck_files <- sort(unique(normalizePath(mageck_files, mustWork = TRUE)))

if (length(mageck_files) == 0L) {
  stop("No *.gene_summary.txt files were found under:\n", MAGECK_DIR)
}

message("\nMAGeCK gene-summary files found: ", length(mageck_files))

# ============================================================
# 10. READ ALL MAGeCK RESULTS
# ============================================================
all_list <- vector("list", length(mageck_files))

for (file_i in seq_along(mageck_files)) {
  message("[", file_i, "/", length(mageck_files), "] ", basename(mageck_files[file_i]))
  all_list[[file_i]] <- read_mageck_gene_summary(mageck_files[file_i])
}

all_results <- data.table::rbindlist(all_list, use.names = TRUE, fill = TRUE)

# ============================================================
# 11. VERIFY EXPECTED T2 RESULTS
# ============================================================
all_results[, `:=`(contains_T2, shift_timing == "T2" | base_timing == "T2" | grepl("(^|_)T2($|_)", 
  contrast_id))]

n_t2_rows <- all_results[contains_T2 == TRUE, .N]

n_t2_contrasts <- all_results[contains_T2 == TRUE, uniqueN(mageck_prefix)]

if (isTRUE(STRICT_EXPECTED_COUNTS) && n_t2_contrasts != EXPECTED_T2_CONTRASTS) {
  stop("Expected ", EXPECTED_T2_CONTRASTS, " T2 contrasts (direct, baseline-vs-T0, drug-vs-T0), but found ", 
    n_t2_contrasts, ".")
}

all_results <- merge(all_results, input_guide_counts[, .(batch, PAO1_ID, input_fullmatch_guides, 
  guide_design_class)], by = c("batch", "PAO1_ID"), all.x = TRUE, sort = FALSE)

missing_input_guide_counts <- all_results[is.na(input_fullmatch_guides)]

if (nrow(missing_input_guide_counts) > 0L) {
  warning(nrow(missing_input_guide_counts), " MAGeCK gene/contrast rows could not be matched to an input full-match guide count.")
}

all_results[, `:=`(retained_fraction, data.table::fifelse(is.finite(input_fullmatch_guides) & input_fullmatch_guides > 
  0 & is.finite(num_guides), num_guides/input_fullmatch_guides, NA_real_))]

all_results[, `:=`(lost_guides_vs_input, data.table::fifelse(is.finite(input_fullmatch_guides) & 
  is.finite(num_guides), input_fullmatch_guides - num_guides, NA_real_))]

all_results[, `:=`(retained_fraction_gt1_flag, is.finite(retained_fraction) & retained_fraction > 
  1 + 1e-12)]

if (any(all_results$retained_fraction_gt1_flag, na.rm = TRUE)) {
  warning(sum(all_results$retained_fraction_gt1_flag, na.rm = TRUE), " rows have MAGeCK num > input full-match guide count. Inspect these rows.")
}

# ============================================================
# 12. MAGeCK-ONLY SIGNIFICANCE CALLS
# ============================================================
# Interpret negative and positive selection separately using MAGeCK FDRs.
# The comparison family determines the biological label; drug/T0 is not an interaction test.
all_results[, `:=`(neg_significant, is.finite(neg_fdr) & neg_fdr < MAGECK_FDR_CUT)]

all_results[, `:=`(pos_significant, is.finite(pos_fdr) & pos_fdr < MAGECK_FDR_CUT)]

all_results[, `:=`(bidirectional_significant, neg_significant & pos_significant)]

all_results[, `:=`(selection_direction, data.table::fcase(bidirectional_significant, "ambiguous_bidirectional", 
  neg_significant, "negative_selection", pos_significant, "positive_selection", default = "not_significant"))]

all_results[, `:=`(selection_state, data.table::fcase(selection_direction == "negative_selection", 
  -1L, selection_direction == "not_significant", 0L, selection_direction == "positive_selection", 
  1L, default = NA_integer_))]

all_results[, `:=`(biological_call, data.table::fcase(comparison_type == "drug_vs_matched_control" & 
  selection_direction == "negative_selection", "sensitizing", comparison_type == "drug_vs_matched_control" & 
  selection_direction == "positive_selection", "tolerance_inducing", comparison_type == "drug_vs_matched_control" & 
  selection_direction == "not_significant", "not_significant", comparison_type == "baseline_post_vs_T0" & 
  selection_direction == "negative_selection", "fitness_decreasing", comparison_type == "baseline_post_vs_T0" & 
  selection_direction == "positive_selection", "fitness_increasing", comparison_type == "baseline_post_vs_T0" & 
  selection_direction == "not_significant", "not_significant", comparison_type == "drug_vs_T0" & 
  selection_direction == "negative_selection", "treated_fitness_decreasing", comparison_type == 
  "drug_vs_T0" & selection_direction == "positive_selection", "treated_fitness_increasing", comparison_type == 
  "drug_vs_T0" & selection_direction == "not_significant", "not_significant", selection_direction == 
  "ambiguous_bidirectional", "ambiguous_bidirectional", default = "not_classified"))]

all_results[, `:=`(mageck_state, selection_state)]

# ============================================================
# 13. VALIDATE CONTRASTS
# ============================================================
# Match imported comparisons against the preparation manifest before pooling
# results. Missing, extra or misclassified comparisons stop the workflow.
contrast_manifest <- unique(all_results[, .(batch, mageck_prefix, contrast_id, shift, base, comparison_type, 
  shift_drug, shift_dose, shift_timing, base_drug, base_dose, base_timing, display_label, source_file)])

data.table::setorder(contrast_manifest, batch, comparison_type, shift_drug, shift_dose, shift_timing)

duplicate_gene_rows <- all_results[, .N, by = .(mageck_prefix, PAO1_ID)][N > 1L]

if (nrow(duplicate_gene_rows) > 0L) {
  data.table::fwrite(duplicate_gene_rows, file.path(OUTPUT_DIR, "ERROR_duplicate_gene_rows.tsv"), 
    sep = "\t")
  stop("Duplicated PAO1_ID rows were found within one or more MAGeCK contrasts. ", "See ERROR_duplicate_gene_rows.tsv.")
}

n_total_contrasts <- data.table::uniqueN(contrast_manifest$mageck_prefix)

n_drug_contrasts <- contrast_manifest[comparison_type == "drug_vs_matched_control", .N]

n_baseline_contrasts <- contrast_manifest[comparison_type == "baseline_post_vs_T0", .N]

n_treated_vs_T0_contrasts <- contrast_manifest[comparison_type == "drug_vs_T0", .N]

n_other_contrasts <- contrast_manifest[comparison_type == "other", .N]

if (n_other_contrasts > 0L) {
  stop(n_other_contrasts, " contrast(s) were classified as 'other'. ", "This aminoglycoside experiment should contain only ", 
    "drug_vs_matched_control, baseline_post_vs_T0, and drug_vs_T0 families.")
}

# Cross-check the completed MAGeCK results against the exact
# preprocessing manifest used to generate the shell commands.
if (isTRUE(VERIFY_AGAINST_PREPROCESS_MANIFEST)) {
  if (!file.exists(PREPROCESS_CONTRAST_MANIFEST_FILE)) {
    stop("Preprocessing contrast manifest is missing:\n", PREPROCESS_CONTRAST_MANIFEST_FILE)
  }
  preprocess_manifest <- data.table::fread(PREPROCESS_CONTRAST_MANIFEST_FILE, sep = "\t", header = TRUE, 
    data.table = TRUE)
  required_preprocess_manifest_columns <- c("batch", "contrast_type", "contrast")
  missing_preprocess_manifest_columns <- setdiff(required_preprocess_manifest_columns, names(preprocess_manifest))
  if (length(missing_preprocess_manifest_columns) > 0L) {
    stop("Preprocessing contrast manifest is missing required column(s): ", paste(missing_preprocess_manifest_columns, 
      collapse = ", "))
  }
  preprocess_manifest[, `:=`(batch, tolower(trimws(as.character(batch))))]
  preprocess_manifest[, `:=`(contrast, trimws(as.character(contrast)))]
  preprocess_manifest[, `:=`(contrast_type, trimws(as.character(contrast_type)))]
  preprocess_manifest[, `:=`(expected_postprocess_type, data.table::fcase(contrast_type == "drug_vs_matched_no_drug", 
    "drug_vs_matched_control", contrast_type == "untreated_post_vs_T0", "baseline_post_vs_T0", 
    contrast_type == "drug_vs_T0", "drug_vs_T0", default = "unexpected_preprocess_type"))]
  if (any(preprocess_manifest$expected_postprocess_type == "unexpected_preprocess_type")) {
    bad_types <- sort(unique(preprocess_manifest[expected_postprocess_type == "unexpected_preprocess_type", 
      contrast_type]))
    stop("Unexpected contrast_type value(s) in preprocessing manifest: ", paste(bad_types, 
      collapse = ", "))
  }
  expected_contrasts <- unique(preprocess_manifest[, .(batch, contrast_id = contrast, expected_postprocess_type)])
  observed_contrasts <- unique(contrast_manifest[, .(batch, contrast_id, observed_postprocess_type = comparison_type)])
  expected_keys <- paste(expected_contrasts$batch, expected_contrasts$contrast_id, sep = "||")
  observed_keys <- paste(observed_contrasts$batch, observed_contrasts$contrast_id, sep = "||")
  missing_result_keys <- setdiff(expected_keys, observed_keys)
  extra_result_keys <- setdiff(observed_keys, expected_keys)
  if (length(missing_result_keys) > 0L) {
    stop(length(missing_result_keys), " contrast(s) from the preprocessing manifest have no MAGeCK gene-summary result.\n", 
      paste(missing_result_keys, collapse = "\n"))
  }
  if (length(extra_result_keys) > 0L) {
    stop(length(extra_result_keys), " MAGeCK result contrast(s) are not present in the preprocessing manifest. ", 
      "These may be stale files.\n", paste(extra_result_keys, collapse = "\n"))
  }
  type_check <- merge(expected_contrasts, observed_contrasts, by = c("batch", "contrast_id"), 
    all = TRUE, sort = FALSE)
  type_mismatch <- type_check[expected_postprocess_type != observed_postprocess_type]
  if (nrow(type_mismatch) > 0L) {
    stop(nrow(type_mismatch), " contrast(s) were parsed into the wrong postprocessing family. ", 
      "Inspect the preprocessing manifest and MAGeCK filenames.")
  }
}

if (isTRUE(STRICT_EXPECTED_COUNTS)) {
  if (n_total_contrasts != EXPECTED_TOTAL_CONTRASTS) {
    stop("Expected ", EXPECTED_TOTAL_CONTRASTS, " MAGeCK contrasts, but found ", n_total_contrasts, 
      ".")
  }
  if (n_drug_contrasts != EXPECTED_DRUG_CONTRASTS) {
    stop("Expected ", EXPECTED_DRUG_CONTRASTS, " drug contrasts, but found ", n_drug_contrasts, 
      ".")
  }
  if (n_baseline_contrasts != EXPECTED_BASELINE_CONTRASTS) {
    stop("Expected ", EXPECTED_BASELINE_CONTRASTS, " baseline post-vs-T0 contrasts, but found ", 
      n_baseline_contrasts, ".")
  }
  if (n_treated_vs_T0_contrasts != EXPECTED_TREATED_VS_T0_CONTRASTS) {
    stop("Expected ", EXPECTED_TREATED_VS_T0_CONTRASTS, " drug-vs-T0 contrasts, but found ", 
      n_treated_vs_T0_contrasts, ".")
  }
}

# ============================================================
# 14. SPLIT THE THREE CONTRAST FAMILIES
# ============================================================
# Keep direct interactions, baseline fitness and total treated fitness in
# separate tables so their calls cannot be mistaken for equivalent biological effects.
# Definitive manuscript interaction catalogue:
# all seven treatment-vs-matched-control comparisons are retained,
# including the longitudinal TOB 0.4 T2 comparison and FBS 60 T1.
drug_results <- all_results[comparison_type == "drug_vs_matched_control"]

# Five independent aminoglycoside T1 conditions used for recurrence
# and cross-condition analyses: four TOB doses and AMK.
# FBS T1 is retained in the full catalogue but excluded here.
drug_results_t1_independent <- drug_results[shift_timing %in% RECURRENCE_TIMINGS & shift_drug %in% 
  RECURRENCE_DRUGS]

# Baseline CRISPRi fitness:
# untreated T1/T2 vs untreated T0.
baseline_results <- all_results[comparison_type == "baseline_post_vs_T0"]

# Total treated fitness relative to the common T0 reference.
# IMPORTANT: these are NOT gene-drug interaction calls.
treated_vs_T0_results <- all_results[comparison_type == "drug_vs_T0"]

drug_results[, `:=`(manuscript_analysis_role, data.table::fcase(shift_timing == "T2", "longitudinal_T2_14_generations", 
  shift_drug == "FBS", "FBS_nonrecurrence", shift_timing %in% RECURRENCE_TIMINGS & shift_drug %in% 
    RECURRENCE_DRUGS, "independent_AG_T1_recurrence", default = "other"))]

drug_results_t1_independent <- drug_results[manuscript_analysis_role == "independent_AG_T1_recurrence"]

t2_drug_results <- drug_results[manuscript_analysis_role == "longitudinal_T2_14_generations"]

# ============================================================
# 14B. ISOLATED TOB 1 NORMALIZATION-SENSITIVITY AUDIT
# ============================================================
# Read the retained auxiliary TOTALNORM gene summary and compare its direction
# with the primary TOB1 result. This file is required even though it is not a primary contrast.
# Its concordance rule affects recurrence support, not the primary all-gene catalogue.
# The TOTALNORM rerun is used ONLY here. It never enters all_results,
# contrast_manifest, the seven-condition catalogue, or any other TOB result.
tob1_totalnorm <- read_tob1_totalnorm_summary(TOB1_TOTALNORM_FILE)

tob1_primary <- drug_results[batch == "b4" & shift_drug == "TOB" & shift_dose == "1" & shift_timing == 
  "T1"]

if (data.table::uniqueN(tob1_primary$mageck_prefix) != 1L) {
  stop("Expected exactly one primary B4 TOB 1 T1 vs matched T1 contrast, found ", data.table::uniqueN(tob1_primary$mageck_prefix), 
    ".")
}

tob1_sensitivity <- merge(tob1_primary, tob1_totalnorm, by = "PAO1_ID", all = TRUE, sort = FALSE)

if (any(is.na(tob1_sensitivity$biological_call))) {
  warning(sum(is.na(tob1_sensitivity$biological_call)), " TOB 1 TOTALNORM genes could not be matched to the primary median-normalized result.")
}

if (any(is.na(tob1_sensitivity$totalnorm_biological_call))) {
  warning(sum(is.na(tob1_sensitivity$totalnorm_biological_call)), " primary TOB 1 genes could not be matched to the TOTALNORM sensitivity rerun.")
}

tob1_sensitivity[, `:=`(normalization_concordance, data.table::fcase(biological_call == "sensitizing" & 
  totalnorm_biological_call == "sensitizing", "concordant_sensitizing", biological_call == "tolerance_inducing" & 
  totalnorm_biological_call == "tolerance_inducing", "concordant_tolerance_inducing", biological_call == 
  "ambiguous_bidirectional" & totalnorm_biological_call == "ambiguous_bidirectional", "concordant_ambiguous", 
  biological_call == "not_significant" & totalnorm_biological_call == "not_significant", "concordant_not_significant", 
  biological_call %in% c("sensitizing", "tolerance_inducing", "ambiguous_bidirectional") & totalnorm_biological_call == 
    "not_significant", "median_only_significant", biological_call == "not_significant" & totalnorm_biological_call %in% 
    c("sensitizing", "tolerance_inducing", "ambiguous_bidirectional"), "total_only_significant", 
  default = "direction_discordant"))]

# Conservative recurrence call for TOB 1 ONLY.
# Every other TOB dose and AMK retain their original median-normalized call.
tob1_sensitivity[, `:=`(recurrence_biological_call, data.table::fcase(normalization_concordance == 
  "concordant_sensitizing", "sensitizing", normalization_concordance == "concordant_tolerance_inducing", 
  "tolerance_inducing", normalization_concordance == "concordant_ambiguous", "ambiguous_bidirectional", 
  default = "not_significant"))]

tob1_sensitivity_summary <- data.table::data.table(metric = c("median_sensitizing", "total_sensitizing", 
  "concordant_sensitizing", "median_tolerance_inducing", "total_tolerance_inducing", "concordant_tolerance_inducing", 
  "median_ambiguous", "total_ambiguous", "direction_discordant", "median_only_significant", "total_only_significant"), 
  n_genes = c(tob1_sensitivity[biological_call == "sensitizing", .N], tob1_sensitivity[totalnorm_biological_call == 
    "sensitizing", .N], tob1_sensitivity[normalization_concordance == "concordant_sensitizing", 
    .N], tob1_sensitivity[biological_call == "tolerance_inducing", .N], tob1_sensitivity[totalnorm_biological_call == 
    "tolerance_inducing", .N], tob1_sensitivity[normalization_concordance == "concordant_tolerance_inducing", 
    .N], tob1_sensitivity[biological_call == "ambiguous_bidirectional", .N], tob1_sensitivity[totalnorm_biological_call == 
    "ambiguous_bidirectional", .N], tob1_sensitivity[normalization_concordance == "direction_discordant", 
    .N], tob1_sensitivity[normalization_concordance == "median_only_significant", .N], tob1_sensitivity[normalization_concordance == 
    "total_only_significant", .N]))

# Add recurrence-specific columns to the five independent AG T1 conditions.
# Defaults = original median-normalized call. Only B4 TOB 1 T1 is overwritten
# with the concordance-filtered sensitivity result.
drug_results_t1_independent[, `:=`(recurrence_biological_call, biological_call)]

drug_results_t1_independent[, `:=`(normalization_sensitivity_rule, "primary_median_unchanged")]

if (isTRUE(USE_TOB1_CONCORDANT_ONLY_FOR_RECURRENCE)) {
  tob1_recurrence_map <- tob1_sensitivity[, .(PAO1_ID, tob1_recurrence_call = recurrence_biological_call, 
    tob1_normalization_concordance = normalization_concordance, tob1_totalnorm_neg_fdr = totalnorm_neg_fdr, 
    tob1_totalnorm_pos_fdr = totalnorm_pos_fdr, tob1_totalnorm_gene_lfc = totalnorm_neg_lfc)]
  drug_results_t1_independent <- merge(drug_results_t1_independent, tob1_recurrence_map, by = "PAO1_ID", 
    all.x = TRUE, sort = FALSE)
  tob1_rows <- drug_results_t1_independent$batch == "b4" & drug_results_t1_independent$shift_drug == 
