  drug_results_t1_independent[non_tob1_rows, `:=`(tob1_recurrence_call = NA_character_, tob1_normalization_concordance = NA_character_, 
    tob1_totalnorm_neg_fdr = NA_real_, tob1_totalnorm_pos_fdr = NA_real_, tob1_totalnorm_gene_lfc = NA_real_)]
} else {
