# 18. RESULT QC — GUIDE SUPPORT PLOTS
# ============================================================
plot_result_support <- function(batch_results, batch_id) {
  plot_dt <- data.table::copy(batch_results)
  plot_dt[, `:=`(plotted_direction, data.table::fcase(selection_direction == "negative_selection", 
    "negative selection", selection_direction == "positive_selection", "positive selection", 
    default = "not significant / ambiguous"))]
  plot_dt[,plotted_good_fraction:=pmax(neg_goods_fraction,pos_goods_fraction,na.rm=TRUE)]
  plot_dt[selection_direction=="negative_selection",plotted_good_fraction:=neg_goods_fraction]
  plot_dt[selection_direction=="positive_selection",plotted_good_fraction:=pos_goods_fraction]
  plot_dt[, `:=`(plotted_fdr, pmin(neg_fdr, pos_fdr, na.rm = TRUE))]
  finite_positive_fdr <- plot_dt[is.finite(plotted_fdr) & plotted_fdr > 0, plotted_fdr]
  fdr_floor <- if (length(finite_positive_fdr) > 0L) {
    min(finite_positive_fdr)
  } else {
    1e-300
  }
  plot_dt[, `:=`(neg_log10_fdr, -log10(pmax(plotted_fdr, fdr_floor)))]
  p <- ggplot2::ggplot(plot_dt, ggplot2::aes(x = plotted_good_fraction, y = neg_log10_fdr)) + 
    ggplot2::geom_point(alpha = 0.35, size = 1) + ggplot2::facet_wrap(~contrast_id, scales = "free_y") + 
    ggplot2::labs(x = "Good sgRNA fraction", y = "-log10(best directional FDR)", title = paste0(toupper(batch_id), 
      " MAGeCK guide-support diagnostic")) + ggplot2::theme_bw(base_size = 10, base_family = BASE_FAMILY) + 
    ggplot2::theme(strip.text = ggplot2::element_text(size = 7))
  p
}

for (batch_id in sort(unique(all_results$batch))) {
  batch_results_i <- all_results[batch == batch_id]
  p_support <- plot_result_support(batch_results = batch_results_i, batch_id = batch_id)
  save_plot_png_pdf(p_support, paste0("QC_04_", batch_id, "_MAGeCK_guide_support"), width = 11, 
    height = 8)
}

