# Reorder direct-interaction matrices to manuscript order where labels match.
reorder_direct_matrix <- function(dt) {
  existing <- setdiff(names(dt), "PAO1_ID")
  desired <- MANUSCRIPT_CONDITION_ORDER[MANUSCRIPT_CONDITION_ORDER %in% existing]
  remaining <- setdiff(existing, desired)
  data.table::setcolorder(dt, c("PAO1_ID", desired, remaining))
  dt
}

